const ImageUploader = (() => {

    let selectedFiles = [];
    let fileInput, dropZoneText, imageErrorSpan;

    let dropZone = document.getElementById('dropZone');
    let previewContainer = document.getElementById('dropzonePreviewContainer');

    const initialize = () => {

        if (!dropZone) return;

        dropZoneText = document.createElement('p');
        dropZoneText.classList.add('dropzone-text');
        dropZoneText.textContent = 'Drag and drop files here to upload';
        dropZone.appendChild(dropZoneText);

        fileInput = document.createElement('input');
        fileInput.type = 'file';
        fileInput.id = dropZone.dataset.name || 'dropzone-image';
        fileInput.name = dropZone.dataset.name || 'dropzone-image[]';
        fileInput.classList.add('dropzone-image-field');
        fileInput.multiple = true;
        fileInput.required = dropZone.dataset.required ? (dropZone.dataset.required == 'true' ? true : false) : false;
        dropZone.appendChild(fileInput);

        imageErrorSpan = document.createElement('div');
        imageErrorSpan.classList.add('dropzone-image-error');
        dropZone.insertAdjacentElement('afterend', imageErrorSpan);

        implement();
    }

    const implement = () => {

        const maxFiles = dropZone.dataset?.maxFiles ? parseInt(dropZone.dataset.maxFiles) : Infinity;
        const imageNames = dropZone.dataset.imageNames && JSON.parse(dropZone.dataset.imageNames);
        const imageSrcs = dropZone.dataset.imageSrcs && JSON.parse(dropZone.dataset.imageSrcs);

        const updatePreviewContainer = () => {
            if (selectedFiles.length) {
                previewContainer.style.display = 'flex';
            } else {
                previewContainer.style.display = 'none';
            }
        }

        const readFiles = (files) => {
            return Promise.all(files.map(file => new Promise((resolve, reject) => {
                const reader = new FileReader();

                reader.onload = (e) => resolve({ file, result: e.target.result });
                reader.onerror = (e) => reject(new Error(`Failed to read file: ${file.name}`));

                reader.readAsDataURL(file);
            })));
        }

        const updateFileInput = (addAll) => {
            const fileList = new DataTransfer();
            const filesToAdd = addAll ? selectedFiles : selectedFiles.slice(0, maxFiles);
            filesToAdd.forEach(obj => fileList.items.add(obj.file));
            fileInput.files = fileList.files;
        }

        const reorderFiles = (fromIndex, toIndex) => {
            if (fromIndex === toIndex) return;

            const element = selectedFiles[fromIndex];
            selectedFiles.splice(fromIndex, 1);
            selectedFiles.splice(toIndex, 0, element);
        }

        const removeFile = (fileToRemove) => {
            selectedFiles.splice(fileToRemove, 1);
            imageErrorSpan.textContent = '';
        }

        const updatePreview = () => {
            while (previewContainer.firstChild) {
                previewContainer.removeChild(previewContainer.firstChild);
            }

            selectedFiles.forEach((fileObj, index) => {
                const previewDiv = document.createElement('div');
                previewDiv.classList.add('dropzone-image-preview');
                previewDiv.dataset.index = index.toString();

                const img = document.createElement('img');
                img.src = fileObj.result;

                const removeButton = document.createElement('button');
                removeButton.innerHTML = '&times;';
                removeButton.classList.add('dropzone-remove-button');
                removeButton.addEventListener('click', () => {
                    removeFile(index);
                    updateFileInput(true);
                    updatePreview();
                    updatePreviewContainer();
                    previewDiv.remove();
                });

                previewDiv.addEventListener('dragstart', (e) => {
                    e.stopPropagation();
                    e.dataTransfer.setData('text/plain', index.toString());
                });

                previewDiv.addEventListener('dragover', (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    previewDiv.classList.add('drag-over');
                });

                previewDiv.addEventListener('dragleave', (e) => {
                    e.stopPropagation();
                    previewDiv.classList.remove('drag-over');
                });

                previewDiv.addEventListener('drop', (e) => {
                    e.stopPropagation();
                    e.preventDefault();

                    previewDiv.classList.remove('drag-over');

                    const targetElement = e.target;
                    const targetElementPreviewDiv = targetElement.closest('.dropzone-image-preview');

                    const fromIndex = parseInt(e.dataTransfer.getData('text/plain'));
                    let toIndex = parseInt(targetElementPreviewDiv.dataset.index);

                    const rect = e.target.getBoundingClientRect();
                    const droppedAtBottomHalf = e.clientY > rect.top + (rect.height / 2);
                    if (droppedAtBottomHalf) {
                        reorderFiles(fromIndex, toIndex);
                        updateFileInput(true);
                        updatePreview();
                    }

                });

                previewDiv.appendChild(img);
                previewDiv.appendChild(removeButton);
                previewContainer.appendChild(previewDiv);
            });
        }

        const handleFiles = (files) => {
            console.log(files);

            const imageFiles = Array.from(files).filter(file => file.type.startsWith('image/'));

            if (selectedFiles.length + imageFiles.length > maxFiles) {
                imageErrorSpan.textContent = `Maximum ${maxFiles} files can be uploaded.`;;
                return;
            }

            imageErrorSpan.textContent = '';
            readFiles(imageFiles).then(newFiles => {
                selectedFiles.push(...newFiles);
                updateFileInput(true);
                updatePreview();
                updatePreviewContainer();
            });
        }

        const handleFilesFromImages = async () => {
            try {
                const fileList = [];

                for (let i = 0; i < imageSrcs.length; i++) {
                    const imageUrl = imageSrcs[i];
                    const imageName = imageNames[i];

                    const response = await fetch(imageUrl, { method: 'GET' });
                    const blob = await response.blob();

                    // Determine file extension and set MIME type accordingly
                    const extension = imageName.split('.').pop()?.toLowerCase();
                    let mimeType = `image/${extension}`;

                    if (mimeType === 'image/jpg') {
                        mimeType = 'image/jpeg'; // Correct common MIME mismatch
                    }

                    const file = new File([blob], imageName, { type: mimeType });
                    fileList.push(file);
                }

                return fileList; // Returning as an array to be passed to handleFiles

            } catch (error) {
                console.error("Error fetching preloaded images:", error);
                throw error;
            }
        };


        dropZone.addEventListener('dragover', (event) => {
            event.stopPropagation();
            event.preventDefault();
            event.dataTransfer.dropEffect = 'copy';
        })

        dropZone.addEventListener('click', (event) => {
            const isRemoveButtonClick = event.target.classList.contains('dropzone-remove-button');
            if (!isRemoveButtonClick) fileInput.click();
        })

        dropZone.addEventListener('drop', (event) => {
            event.stopPropagation();
            event.preventDefault();
            const files = event.dataTransfer.files;
            if (files) handleFiles(files);
        })

        fileInput.addEventListener('change', (event) => {
            handleFiles(event.target.files);
        })

        if (imageNames && imageSrcs && imageNames.length == imageSrcs.length) {
            handleFilesFromImages().then(files => {
                handleFiles(files);
            }).catch(error => {
                console.error("Error handling files:", error);
            });
        }
    }

    if (dropZone, previewContainer) return { initialize };
})();

ImageUploader.initialize();